-- Lessons: link each question to the Skill Jar lesson it belongs to, so the link under an answer explanation names the
-- lesson ("Technical Substrate (MSO Foundations)"). A lesson has no web address of its own, so it links to its course.
-- Questions with no lesson keep the course-level link. Additive and safe to re-run: it never overwrites a lesson the
-- admin has picked. Generated by scripts/generate-submodule-seed-sql.ts.

-- 1. A question can point at one lesson (a topic of its submodule that names a lesson)
alter table quiz_questions
  add column if not exists topic_id integer references quiz_skilljar_topics(id) on delete set null;

-- 2. The Accelerators & IP Contribution course also needs a submodule row under the domains of the questions that
--    belong to it by lesson (so its module has 5 questions: 3 moved in, and the 2 it already had)
with extra(track, domain, title, url, position, description) as (values
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$Accelerators & IP Contribution$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/accelerators-ip-contribution$q$, 5, $q$Getting a finished build ready to be reused, reviewed and deployed elsewhere.$q$),
  ($q$developer$q$, $q$Security and Safety$q$, $q$Accelerators & IP Contribution$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/accelerators-ip-contribution$q$, 5, $q$Getting a finished build ready to be reused, reviewed and deployed elsewhere.$q$)
),
ins as (
  insert into quiz_submodules (module_id, title, order_index, course_position, description)
  select m.id, e.title,
         coalesce((select max(s.order_index) from quiz_submodules s where s.module_id = m.id), 0) + 1,
         e.position, e.description
  from extra e join quiz_modules m on m.title = e.domain and m.track = e.track
  on conflict (module_id, title) do nothing
  returning id
)
select count(*) as accelerator_rows_added from ins;

insert into quiz_skilljar_topics (submodule_id, course_title, lesson_title, url, order_index)
select sm.id, $q$Accelerators & IP Contribution$q$, null, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/accelerators-ip-contribution$q$, 1
from quiz_submodules sm
where sm.title = $q$Accelerators & IP Contribution$q$
  and not exists (select 1 from quiz_skilljar_topics t where t.submodule_id = sm.id and t.lesson_title is null);

-- 3. Questions that belong to Accelerators & IP Contribution by lesson move to that course (matched by domain and exact text)
with mv(track, domain, question) as (values
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$A team changes a tool's input schema in a breaking way. What must they do to avoid breaking existing integrations?$q$),
  ($q$developer$q$, $q$Security and Safety$q$, $q$In a Claude application, who has higher inherent trust: the operator or the end user?$q$),
  ($q$developer$q$, $q$Security and Safety$q$, $q$A SaaS platform serves many organisations using the same Claude integration. What must be enforced to prevent data leakage between tenants?$q$)
)
update quiz_questions qq
set submodule_id = sm.id, topic_id = null
from mv
join quiz_modules m on m.title = mv.domain and m.track = mv.track
join quiz_submodules sm on sm.module_id = m.id and sm.title = $q$Accelerators & IP Contribution$q$
where qq.module_id = m.id and qq.question = mv.question and qq.submodule_id is distinct from sm.id;

