  ($q$developer$q$, $q$Security and Safety$q$, $q$An agent can send emails on behalf of executives. Which control is most important before each send?$q$, $q$Production Engineering, Evals & Security$q$, $q$Security$q$),
  ($q$developer$q$, $q$Security and Safety$q$, $q$A user asks Claude to reveal its system prompt. The operator has instructed Claude to keep the system prompt confidential. How should Claude respond?$q$, $q$Production Engineering, Evals & Security$q$, $q$Security$q$),
  ($q$developer$q$, $q$Security and Safety$q$, $q$A mental health application built on Claude receives a message from a user describing thoughts of self-harm. What should the application be configured to do?$q$, $q$Production Engineering, Evals & Security$q$, $q$Security$q$),
  ($q$developer$q$, $q$Security and Safety$q$, $q$A user attempts a "persona jailbreak" by asking Claude to roleplay as an AI with no restrictions. Which system-level defence is most robust?$q$, $q$Production Engineering, Evals & Security$q$, $q$Security$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$A team wants to reuse the same integration code across dev, staging, and prod with different model versions and system prompts. What is the best approach?$q$, $q$Accelerators & IP Contribution$q$, $q$Deployment & Versioning$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$A team changes their system prompt and observes a quality regression in production. What practice would have made this easier to detect and roll back?$q$, $q$Accelerators & IP Contribution$q$, $q$Deployment & Versioning$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$A team changes a tool's input schema in a breaking way. What must they do to avoid breaking existing integrations?$q$, $q$Accelerators & IP Contribution$q$, $q$Deployment & Versioning$q$),
  ($q$developer$q$, $q$Security and Safety$q$, $q$In a Claude application, who has higher inherent trust: the operator or the end user?$q$, $q$Accelerators & IP Contribution$q$, $q$Trust Boundaries$q$),
  ($q$developer$q$, $q$Security and Safety$q$, $q$A SaaS platform serves many organisations using the same Claude integration. What must be enforced to prevent data leakage between tenants?$q$, $q$Accelerators & IP Contribution$q$, $q$Trust Boundaries$q$)
)
update quiz_questions qq
set topic_id = t.id
from ptr p
join quiz_modules m on m.title = p.domain and m.track = p.track
join quiz_submodules sm on sm.module_id = m.id and sm.title = p.course
join quiz_skilljar_topics t on t.submodule_id = sm.id and t.lesson_title = p.lesson
where qq.module_id = m.id and qq.question = p.question and qq.submodule_id = sm.id and qq.topic_id is null;

-- Check: questions per course and lesson (a row with lesson = null is the course link only)
select m.track, sm.title as course, t.lesson_title as lesson, count(qq.id) as questions
from quiz_questions qq
join quiz_submodules sm on sm.id = qq.submodule_id
join quiz_modules m on m.id = qq.module_id
left join quiz_skilljar_topics t on t.id = qq.topic_id
group by m.track, sm.title, t.lesson_title
order by m.track, sm.title, t.lesson_title nulls first;
